def count_valid_triples(binary_rep):
    n = int(binary_rep, 2)
    MOD = 998244353
    count = 0
    for i in range(3):
        for j in range(i + 1, 3):
            a = i & (n - 1)
            b = j & (n - 1)
            for k in range(3):
                if i == k:
                    continue
                delta = (a ^ b) ^ (i ^ k) | b ^ (j | (k ^ b))
                if delta <= n - 1 and delta < n and delta < 2 * (i ^ a):
                    count += 1
                    count = count % MOD
    return count
