from math import inf

def is_direction(line):
    """Determine if the laser beam/cone direction is straight/lateral/linear"""
    splitline = line.split()
    angle = float(splitline[splitline.index("street") + 1])
    if angle == 180.0:
        return "straight"
    elif 80 <= angle < 180:
        if angle < 120 + 8:
            return "lateral"
        else:
            return "linear"
    elif angle == 0.0:
        return "lateral"
    else:
        return "linear"

def get_direction(n, a):
    directions = ["linear"] * n
    nonzero_dirs = [len(directions)]
    for (i, x) in enumerate(a):
        if x == 0:
            nonzero_dirs.append(i)
        else:
            directions[i-1] = directions[x - 1]
    for (i, x) in enumerate(a):
        if x > 0:
            directions[x - 1] = "lateral"
        else:
            directions[abs(x) - 1] = "linear"
    for i in nonzero_dirs:
        directions[i] = is_direction(line=directions[i])
        # use the same active direction for all non-null before, so the effect is the minimal possible
    return directions

def process(test_case):
    n = int(input())
    a = list(map(int, input().split()))

    direction = get_direction(n, a)
    print(n)
    print("".join(direction))

process(test_case=3)
