    count_c = s.count('c')

    # Number of valid substrings of letters 'a', 'b', 'c'
    k1 = 2 * count_a + 1 + count_b + count_c
    k2 = 2 * count_b + 1 + count_a + count_c
    k3 = 2 * count_c + 1 + count_a + count_b

    # Calculate total number of valid substrings
    n = len(s)
    total = 0
    for i in range(n):
        if s[i] == 'a' and i > 0 and s[i-1] != s[i]:
            total += min(count_a, n - i - 1) + min(count_b, n - i - 1)
        if s[i] == 'b' and i > 0 and s[i-1].lower() != s[i].lower():
            total += count_a + count_b - min(count_a, count_b)
        if s[i] == 'c' and i > 0 and s[i-1].lower() != s[i].lower():
            total += count_b + count_c - min(count_b, count_c)

    # Store counts of strings from k1 to k3
    # Initialize result
    mod, res = (10 ** 9 + 7, 1)

    if n == 1:
        return res
    elif n == 2:
        if s[0] == 'a':
            res += 1
        elif s[1] == 'a':
            res -= 1

