    grid = [['.'] * n for _ in range(n)]
    for i, j in enumerate(beam_arrangement):
        row, col = (i % n, i // n)
        grid[row][col] = 'X'
        # Mirror placement logic
        if col == 0:
            grid[row][n-1] = '/'
            if (i + j) % 2 == 0:
                grid[row-1][0] = '\\'
        else:
            grid[row][0] = '\\'
            if (i + j) % 2 == 1:
                grid[row-1][n-1] = '/'
    for row in grid:
        print(''.join(row))

def calculate_max_lasers(n, beam_arrangement):
    count = max_beam = 0
    for i in range(n):
        count += beam_arrangement[i]
        max_beam = max(max_beam, count)
    return max_beam

