def triple_sides(n):
    def count_sides(limit):
        cnt = 0
        for i in range(limit // 2 + 1):
            a = pow(2, i, MOD - 1)
            b = pow(2, i + 1, MOD - 1) - pow(2, i, MOD - 1) * i
            c = pow(2, i + 2, MOD - 1) - pow(2, i, MOD - 1) * (i + 1)
            if a + b > b + c:
                ans = 1 + (b - (c + c) + 1) // 2
                cnt += ans
        return cnt
    limit = 1
    while limit <= n:
        limit *= 2
    return count_sides(limit - 1) * 2 % MOD + count_sides(limit // 2 + 1)

