def process_query_type_1(vertex, distances):
    max_distance = 0
    vertex_with_max_distance = 0
    visited = [False] * len(distances)
    queue = []
    heapq.heappush(queue, (0, vertex))

    while queue:
        distance, current_vertex = heapq.heappop(queue)

        if visited[current_vertex]:
            continue

        visited[current_vertex] = True
        max_distance = max(max_distance, distance)

