def process_queries(graph, queries):
    distances = [[] for _ in range(len(graph))]
    distances.reverse()

    for i in range(len(graph)):
        for j in range(len(graph)):
            distance = sum(graph[i][k] for k in range(len(graph[i])) if j in distances[k])
            heapq.heappush(distances[i], distance)

    for query in queries:
