from collections import deque

def max_pocket_sum(n, k, arrays):
    dp = [[0] * i for i in range(n + 1)]  # dynamic programming table
    que = deque([(0, 0)])  # (array_index, elements_in_pocket)

    for _ in range(k):
        pivot, elements_pocket = que.popleft()
        for j in range(pivot + 1, n + 1):
            if que and que[0][0] < j:
                pivot, elements_pocket = que.popleft()
            dp[j] = que[0][1] + max(arrays[j - 1][i + 1] for i in range(elements_pocket))
            if j == n - 1:
                que.append((j, dp[j]))
            else:
                que.append((j, dp[j]) if dp[j] > dp[j + 1] else (j + 1, dp[j + 1]))

    return dp[-2]

