def calculate_possible_strings(s):
    mod = 998244353
    a, b, c = 1, 1, 1
    for char in s:
        if char == 'a':
            a = 2 * c % mod
        elif char == 'b':
            b = 2 * a % mod
        else:
            c = 2 * b % mod
    return (a + b + c) % mod

